(* [comment removed for export] *)
Definition z4s31_D2_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x10 x11 x12 x13 x15 x16 x17 x18 x19 x20 x22 x23 x24 x25 x26 x29 x30 x31 : word)
         (SPF DT4 DBL DBH DST dcap tl P B CZ : Z) (cells : list deltX2) (obuf : list Z),
    z4s1_dctx RNG mm SPF DT4 DBL DBH DST dcap tl -> mem_inv asegs mm ->
    x2_table_ok cells tl -> bytes_at asegs mm DT4 (firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells)) ->
    u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
    rw_cells asegs mm (SPF + 312) [C8 (Z_to_bv 64 DT4)] -> 0 <= CZ < 2^64 ->
    DST <= P -> P + 2 <= DST + dcap -> 0 <= B <= 7 ->
    (forall (mm' : amem) (BZ PZ : Z) (k1 k7 k14 k30 k31 : word),
       munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       (exists obuf' : list Z, u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
       0 <= BZ <= 19 -> P + 1 <= PZ <= P + 2 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SPF) gp tp x5 x6 k7 x8 (Z_to_bv 64 BZ) x10 k1 x12 x13 k14 x15 x16 x17 x18 x19
                                 x20 (Z_to_bv 64 PZ) x22 x23 x24 x25 x26 (Z_to_bv 64 2147450880) (Z_to_bv 64 (64 - tl)) x6 k30
                                 k31)
                            F (Z_to_bv 64 0x8a5d4) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SPF) gp tp x5 x6 x7 x8 (Z_to_bv 64 B) x10 x11 x12 x13 (Z_to_bv 64 CZ) x15 x16 x17
                             x18 x19 x20 (Z_to_bv 64 P) x22 x23 x24 x25 x26 (Z_to_bv 64 2147450880) (Z_to_bv 64 (64 - tl)) x29
                             x30 x31)
                        F (Z_to_bv 64 0x8a538) fc None mm (seg_rom asegs)).

Ltac z4s31_tab TOK TB :=
  lazymatch type of TB with bytes_at ?segs ?mm ?DT4 (firstn (Z.to_nat (4 * 2^?tl)) (x2_bytes' ?cells)) =>
  let TF := fresh "TF" in pose proof (z4_x2tab_fact_tl mm DT4 cells tl TOK TB) as TF;
  let TLR := fresh "TLR" in pose proof TOK as (TLR & _); unfold HUF_TABLELOG_MAX in TLR;
  let P2 := fresh "P2" in
  assert (P2 : 2 <= 2^tl <= 4096) by (split; [change 2 with (2^1) at 1 | change 4096 with (2^12)]; apply Z.pow_le_mono_r; lia);
  let TL := fresh "TL" in
  assert (TL : Z.of_nat (length (firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells))) = 4 * 2^tl)
    by (let TLz := fresh in pose proof TOK as (_ & TLz & _); unfold FseNCount.Zlength in TLz;
        rewrite length_firstn, x2_bytes'_length; rewrite Nat2Z.inj_min, Z2Nat.id by lia; lia)
  end.

